    {
      "id": 1,
      "claim": "The enzymatic activity that adds phosphate groups to cellular proteins is performed by kinases (phosphorylation).",
      "evidence": "Biochemistry defines kinases as enzymes that transfer a phosphate group from ATP to a substrate; protein phosphatases remove phosphate groups.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The src oncogene encodes a protein that possesses intrinsic tyrosine kinase activity.",
      "evidence": "Molecular studies of v‑src and c‑src show the product (pp60src) is a non‑receptor tyrosine kinase that phosphorylates tyrosine residues on target proteins.",
      "weight": 0.45,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Among the answer choices, only \"Tyrosine kinase\" (option D) both adds phosphate groups to proteins and is the activity encoded by src; the other options (protein phosphatase, adenylate cyclase, G‑protein‑linked receptor) do not satisfy both criteria.",
      "evidence": "Protein phosphatase removes phosphates; adenylate cyclase synthesizes cAMP, not protein phosphorylation; G‑protein‑linked receptors are receptors, not enzymes that phosphorylate proteins.",
      "weight": 0.25,
      "depends_on": [1, 2]
    }
  ],
  "answer": "D",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Protein phosphatases remove phosphate groups rather than add them."
    },
    {
      "answer": "B",
      "reason_rejected": "Adenylate cyclase generates cAMP from ATP; it does not phosphorylate proteins."
    },
    {
      "answer": "C",
      "reason_rejected": "G‑protein‑linked receptors are membrane receptors that signal via G proteins; they are not kinases that add phosphate groups to proteins."
    }
  ]
}
